// Self-hosted via @fontsource — no build-time Google Fonts fetch.
import "@fontsource/sora";
import "@fontsource/noto-sans-kr";

export const sora = { variable: "" };
export const notoSansKR = { variable: "" };

"use client";

import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

function subscribe(onChange: () => void): () => void {
  const mql = window.matchMedia(QUERY);
  mql.addEventListener("change", onChange);
  return () => mql.removeEventListener("change", onChange);
}

function getSnapshot(): boolean {
  return window.matchMedia(QUERY).matches;
}

function getServerSnapshot(): boolean {
  return false;
}

/**
 * True when the OS asks for reduced motion.
 * SSR-safe: the server snapshot is `false`; on the client the real value is
 * read synchronously, and live changes to the setting re-render immediately.
 */
export function usePrefersReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

"use client";

import { useEffect, useRef } from "react";
import { usePrefersReducedMotion } from "./usePrefersReducedMotion";

/**
 * Reveals descendants marked with [data-reveal] as they enter the viewport,
 * by adding an `is-visible` class (the name styles.css expects). Pre-reveal
 * states (opacity/translate) live in styles.css and are gated behind the
 * `.neon-js` root class, so all content is fully visible when JavaScript
 * never runs.
 *
 * Elements that intersect in the same observer batch are staggered 80ms apart
 * — the street's cadence.
 */
export function useReveal<T extends HTMLElement = HTMLElement>() {
  const ref = useRef<T | null>(null);
  const reduced = usePrefersReducedMotion();

  useEffect(() => {
    const root = ref.current;
    if (!root) return;
    const targets = Array.from(
      root.querySelectorAll<HTMLElement>("[data-reveal]"),
    );

    if (reduced || !("IntersectionObserver" in window)) {
      for (const el of targets) el.classList.add("is-visible");
      return;
    }

    const io = new IntersectionObserver(
      (hits) => {
        let batch = 0;
        for (const hit of hits) {
          if (!hit.isIntersecting) continue;
          const el = hit.target as HTMLElement;
          el.style.transitionDelay = `${batch * 80}ms`;
          el.classList.add("is-visible");
          io.unobserve(el);
          batch += 1;
        }
      },
      { threshold: 0.16, rootMargin: "0px 0px -8% 0px" },
    );
    for (const el of targets) io.observe(el);
    return () => io.disconnect();
  }, [reduced]);

  return ref;
}

"use client";

import { useEffect, useRef, type CSSProperties } from "react";
import "./styles.css";
import { sora, notoSansKR } from "./fonts";
import { useReveal } from "./hooks/useReveal";
import { usePrefersReducedMotion } from "./hooks/usePrefersReducedMotion";

const TITLE = "MESH";

/**
 * MESH 메쉬 — a gradient studio. The signature is an animated CSS mesh: five
 * large radial color blobs (coral, violet, teal, gold, magenta) on a dark
 * backdrop, each drifting on its own @keyframes so the field slowly breathes.
 * No canvas — it's pure layered radial gradients in DOM. The pointer adds a
 * gentle parallax to the blob layer (input-only). The wordmark "MESH" is
 * white with a stacked multi-color text-shadow glow drawn from the mesh hues.
 *
 * `.mesh-js` is added on mount so the no-JS markup is the finished page.
 */
export default function MeshPage() {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const reduced = usePrefersReducedMotion();
  const revealRef = useReveal<HTMLDivElement>();
  const stageRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    root.classList.add("mesh-js");
    const id = requestAnimationFrame(() => root.classList.add("is-mounted"));
    window.parent?.postMessage({ type: "oneshot:ready", slug: "mesh" }, "*");
    return () => cancelAnimationFrame(id);
  }, []);

  // Pointer parallax — the blob layer drifts gently with the cursor.
  useEffect(() => {
    const stage = stageRef.current;
    if (!stage || reduced) return;
    let raf = 0;
    let tx = 0;
    let ty = 0;
    let cx = 0;
    let cy = 0;
    const onMove = (ev: PointerEvent) => {
      const r = stage.getBoundingClientRect();
      if (r.width < 4) return;
      tx = ((ev.clientX - r.left) / r.width - 0.5) * 2; // -1..1
      ty = ((ev.clientY - r.top) / r.height - 0.5) * 2;
      if (!Number.isFinite(tx) || !Number.isFinite(ty)) return;
      if (!raf) raf = requestAnimationFrame(tick);
    };
    const tick = () => {
      cx += (tx - cx) * 0.08;
      cy += (ty - cy) * 0.08;
      stage.style.setProperty("--ms-px", `${(cx * 3).toFixed(1)}vmax`);
      stage.style.setProperty("--ms-py", `${(cy * 3).toFixed(1)}vmax`);
      if (Math.abs(tx - cx) > 0.01 || Math.abs(ty - cy) > 0.01) {
        raf = requestAnimationFrame(tick);
      } else {
        raf = 0;
      }
    };
    window.addEventListener("pointermove", onMove, { passive: true });
    return () => {
      window.removeEventListener("pointermove", onMove);
      if (raf) cancelAnimationFrame(raf);
    };
  }, [reduced]);

  return (
    <div ref={rootRef} className={`${sora.variable} ${notoSansKR.variable} mesh-root`}>
      <div ref={stageRef} className="mesh-field" aria-hidden="true">
        <span className="mesh-blob mesh-blob--coral" />
        <span className="mesh-blob mesh-blob--violet" />
        <span className="mesh-blob mesh-blob--teal" />
        <span className="mesh-blob mesh-blob--gold" />
        <span className="mesh-blob mesh-blob--magenta" />
      </div>
      <div ref={revealRef} className="mesh-doc">
        <header className="mesh-hero">
          <p className="mesh-kicker">
            <span lang="ko">그라디언트 스튜디오</span> · A FIELD OF COLOR · 2026
          </p>
          <h1 className="mesh-title" aria-label={TITLE}>
            <span className="mesh-glow" aria-hidden="true">
              {TITLE.split("").map((ch, i) => (
                <span key={i} className="mesh-glyph" style={{ "--ms-i": i } as CSSProperties}>
                  {ch}
                </span>
              ))}
            </span>
          </h1>
          <p className="mesh-title__ko" lang="ko">메쉬</p>
          <p className="mesh-sub">
            <span lang="ko">색의 장.</span> A field of color.
          </p>
          <p className="mesh-hint" lang="ko">움직여 보세요 — 색의 장이 흐릅니다.</p>
        </header>

        <main>
          <section className="mesh-grid">
            {[
              { ko: "코랄", en: "Coral", n: "01" },
              { ko: "바이올렛", en: "Violet", n: "02" },
              { ko: "티얼", en: "Teal", n: "03" },
              { ko: "골드", en: "Gold", n: "04" },
              { ko: "마젠타", en: "Magenta", n: "05" },
            ].map((c, i) => (
              <article
                key={i}
                className="mesh-card"
                data-reveal
                style={{ "--ms-d": i * 80 } as CSSProperties}
              >
                <span className="mesh-card__n">{c.n}</span>
                <span className="mesh-card__en">{c.en}</span>
                <span className="mesh-card__ko" lang="ko">{c.ko}</span>
              </article>
            ))}
          </section>

          <section className="mesh-lead" data-reveal>
            <p className="mesh-lead__p">
              <span lang="ko">
                우리는 색을 섞지 않는다, 겹친다. 다섯 개의 빛이 각자의 속도로
                떠다니며 만나는 곳마다 새로운 장이 된다.
              </span>{" "}
              We don't mix color — we layer it. Five lights drift at their own
              pace, and where they meet a new field begins.
            </p>
          </section>
        </main>

        <footer className="mesh-foot">
          <span>MESH · 2026</span>
          <span lang="ko">메쉬 — 서울</span>
        </footer>
      </div>
    </div>
  );
}

.mesh-root {
  --ms-bg: #0e0a1a;
  --ms-deep: #08050f;
  --ms-text: #f4eefb;
  --ms-mute: #a896c4;
  --ms-coral: #ff7a59;
  --ms-violet: #8b5cff;
  --ms-teal: #2fe0c8;
  --ms-gold: #ffce4d;
  --ms-magenta: #ff5ec7;
  --ms-font-display: "Sora", system-ui, sans-serif;
  --ms-font-kr: "Noto Sans KR", sans-serif;
  --ms-ease: cubic-bezier(0.16, 1, 0.3, 1);
  --ms-px: 0vmax;
  --ms-py: 0vmax;

  position: relative;
  min-height: 100vh;
  margin: 0;
  background: var(--ms-bg);
  color: var(--ms-text);
  font-family: var(--ms-font-kr);
  font-weight: 300;
  line-height: 1.6;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}
.mesh-root ::selection { background: var(--ms-coral); color: var(--ms-deep); }

/* ---- The animated mesh field (pure CSS, no canvas) ---- */
.mesh-field {
  position: fixed;
  inset: -20%;
  z-index: 0;
  pointer-events: none;
  background: var(--ms-deep);
  transform: translate3d(var(--ms-px), var(--ms-py), 0);
  transition: transform 320ms var(--ms-ease);
}
.mesh-blob {
  position: absolute;
  width: 56vmax;
  height: 56vmax;
  border-radius: 50%;
  filter: blur(60px);
  opacity: 0.8;
  mix-blend-mode: screen;
  will-change: transform;
}
.mesh-blob--coral {
  left: -8%; top: -6%;
  background: radial-gradient(circle at 50% 50%, var(--ms-coral), transparent 62%);
  animation: ms-drift-a 22s var(--ms-ease) infinite alternate;
}
.mesh-blob--violet {
  right: -10%; top: -4%;
  background: radial-gradient(circle at 50% 50%, var(--ms-violet), transparent 62%);
  animation: ms-drift-b 26s var(--ms-ease) infinite alternate;
}
.mesh-blob--teal {
  left: 30%; bottom: -12%;
  background: radial-gradient(circle at 50% 50%, var(--ms-teal), transparent 62%);
  animation: ms-drift-c 30s var(--ms-ease) infinite alternate;
}
.mesh-blob--gold {
  right: 8%; bottom: -10%;
  background: radial-gradient(circle at 50% 50%, var(--ms-gold), transparent 60%);
  animation: ms-drift-d 24s var(--ms-ease) infinite alternate;
}
.mesh-blob--magenta {
  left: 4%; top: 38%;
  background: radial-gradient(circle at 50% 50%, var(--ms-magenta), transparent 60%);
  animation: ms-drift-e 28s var(--ms-ease) infinite alternate;
}
@keyframes ms-drift-a {
  0% { transform: translate3d(0, 0, 0) scale(1); }
  100% { transform: translate3d(12vmax, 8vmax, 0) scale(1.18); }
}
@keyframes ms-drift-b {
  0% { transform: translate3d(0, 0, 0) scale(1.1); }
  100% { transform: translate3d(-10vmax, 10vmax, 0) scale(0.92); }
}
@keyframes ms-drift-c {
  0% { transform: translate3d(0, 0, 0) scale(0.95); }
  100% { transform: translate3d(8vmax, -10vmax, 0) scale(1.15); }
}
@keyframes ms-drift-d {
  0% { transform: translate3d(0, 0, 0) scale(1.05); }
  100% { transform: translate3d(-12vmax, -6vmax, 0) scale(0.9); }
}
@keyframes ms-drift-e {
  0% { transform: translate3d(0, 0, 0) scale(0.9); }
  100% { transform: translate3d(14vmax, -8vmax, 0) scale(1.2); }
}
@media (prefers-reduced-motion: reduce) {
  .mesh-blob { animation: none; }
}

.mesh-doc {
  position: relative;
  z-index: 1;
  max-width: 1180px;
  margin: 0 auto;
  padding: clamp(1.5rem, 4vw, 3.5rem);
}

/* ---- Hero ---- */
.mesh-hero {
  min-height: 86vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: clamp(3rem, 10vh, 7rem) 0 2rem;
}
.mesh-kicker {
  margin: 0 0 1.4rem;
  font-family: var(--ms-font-display);
  font-size: clamp(0.72rem, 1.1vw, 0.86rem);
  font-weight: 400;
  letter-spacing: 0.42em;
  text-transform: uppercase;
  color: var(--ms-coral);
  mix-blend-mode: screen;
}
.mesh-title {
  margin: 0;
  font-family: var(--ms-font-display);
  font-weight: 800;
  font-size: clamp(3rem, 16vw, 13rem);
  line-height: 0.86;
  letter-spacing: -0.03em;
}
/* White wordmark with a stacked multi-color glow drawn from the mesh hues —
   the wordmark is illuminated by its own field. */
.mesh-glow {
  display: inline-block;
  color: #fff;
  text-shadow:
    0 0 18px rgba(255, 122, 89, 0.7),
    0 0 36px rgba(139, 92, 255, 0.6),
    0 0 60px rgba(47, 224, 200, 0.5),
    0 0 90px rgba(255, 94, 199, 0.45),
    0 0 120px rgba(255, 206, 77, 0.35);
}
.mesh-glyph { display: inline-block; }
.mesh-title__ko {
  margin: 0.6rem 0 0;
  font-family: var(--ms-font-kr);
  font-weight: 300;
  font-size: clamp(1rem, 2.4vw, 1.6rem);
  letter-spacing: 0.42em;
  color: var(--ms-text);
  opacity: 0.8;
}
.mesh-sub {
  margin: 1.6rem 0 0.4rem;
  font-family: var(--ms-font-display);
  font-size: clamp(1.05rem, 1.9vw, 1.4rem);
  font-weight: 400;
}
.mesh-sub span[lang="ko"] { color: var(--ms-mute); margin-right: 0.5rem; }
.mesh-hint {
  margin: 0;
  font-size: 0.86rem;
  color: var(--ms-teal);
  opacity: 0.85;
}

/* ---- Grid cards (glass chips over the mesh) ---- */
.mesh-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: clamp(0.8rem, 1.4vw, 1.1rem);
  padding: clamp(1rem, 3vw, 2rem) 0;
}
.mesh-card {
  position: relative;
  padding: clamp(1.1rem, 2.2vw, 1.6rem);
  border-radius: 18px;
  min-height: 140px;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  justify-content: flex-end;
  background: rgba(20, 14, 32, 0.42);
  border: 1px solid rgba(255, 255, 255, 0.12);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.14), 0 24px 48px -28px rgba(4, 2, 10, 0.9);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
}
.mesh-card:nth-child(1) { box-shadow: inset 0 1px 0 rgba(255,255,255,0.14), 0 0 40px -10px rgba(255,122,89,0.4); }
.mesh-card:nth-child(2) { box-shadow: inset 0 1px 0 rgba(255,255,255,0.14), 0 0 40px -10px rgba(139,92,255,0.4); }
.mesh-card:nth-child(3) { box-shadow: inset 0 1px 0 rgba(255,255,255,0.14), 0 0 40px -10px rgba(47,224,200,0.4); }
.mesh-card:nth-child(4) { box-shadow: inset 0 1px 0 rgba(255,255,255,0.14), 0 0 40px -10px rgba(255,206,77,0.4); }
.mesh-card:nth-child(5) { box-shadow: inset 0 1px 0 rgba(255,255,255,0.14), 0 0 40px -10px rgba(255,94,199,0.4); }
.mesh-card__n { font-family: var(--ms-font-display); font-weight: 800; font-size: 0.8rem; color: var(--ms-coral); letter-spacing: 0.2em; }
.mesh-card__en { font-family: var(--ms-font-display); font-weight: 600; font-size: 1.15rem; }
.mesh-card__ko { font-size: 0.9rem; color: var(--ms-mute); }

.mesh-lead {
  padding: clamp(2.5rem, 6vw, 4rem) 0;
  border-top: 1px solid rgba(255, 122, 89, 0.18);
}
.mesh-lead__p {
  margin: 0 auto;
  max-width: 62ch;
  font-family: var(--ms-font-display);
  font-weight: 300;
  font-size: clamp(1.15rem, 2.4vw, 1.7rem);
  line-height: 1.5;
  text-align: center;
}
.mesh-lead__p span[lang="ko"] {
  display: block;
  font-family: var(--ms-font-kr);
  color: var(--ms-mute);
  font-size: 0.74em;
  margin-bottom: 0.6em;
}

.mesh-foot {
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.5rem;
  padding: clamp(2rem, 5vw, 3rem) 0;
  border-top: 1px solid rgba(255, 122, 89, 0.18);
  font-size: 0.8rem;
  letter-spacing: 0.06em;
  color: var(--ms-mute);
  font-family: var(--ms-font-display);
}

/* ---- Reveal gating ---- */
.mesh-js [data-reveal] {
  opacity: 0;
  transform: translateY(26px);
  transition: opacity 800ms var(--ms-ease), transform 800ms var(--ms-ease);
  transition-delay: calc(var(--ms-d, 0) * 1ms);
}
.mesh-js [data-reveal].is-visible { opacity: 1; transform: none; }
.mesh-js .mesh-glyph {
  opacity: 0;
  transform: translateY(0.35em);
  display: inline-block;
  transition: opacity 700ms var(--ms-ease), transform 700ms var(--ms-ease);
  transition-delay: calc(var(--ms-i) * 70ms + 150ms);
}
.mesh-js.is-mounted .mesh-glyph { opacity: 1; transform: none; }

@media (prefers-reduced-motion: reduce) {
  .mesh-js [data-reveal], .mesh-js .mesh-glyph {
    opacity: 1 !important; transform: none !important; transition: none !important;
  }
}
.mesh-root :focus-visible { outline: 2px solid var(--ms-coral); outline-offset: 3px; }
